    fields: Pick<MPTokenIssuanceSet, "Holder" | "Flags">,
  ): Promise<void> {
    const tx: MPTokenIssuanceSet = {
      TransactionType: "MPTokenIssuanceSet",
      Account: this.issuerWallet.address,
      MPTokenIssuanceID: this.requireIssuanceId(),
      ...fields,
    };
