import { Client, Wallet, xrpToDrops } from "xrpl";

const client = new Client("wss://s.altnet.rippletest.net:51233");
await client.connect();

const issuer = Wallet.fromSeed("<TESTNET_SEED_REDACTED>");

async function submit(tx, wallet) {
  const res = await client.submitAndWait(tx, { wallet, autofill: true });
  const meta = res.result.meta;
  const result = typeof meta === "string" ? "BINARY" : meta.TransactionResult;
  return { result, meta };
}

async function fundXrp(dest, amt) {
  await submit(
    { TransactionType: "Payment", Account: issuer.address, Destination: dest, Amount: xrpToDrops(amt) },
    issuer,
  );
}

const holder = Wallet.generate();
const peer = Wallet.generate();
await fundXrp(holder.address, "15");
await fundXrp(peer.address, "15");
console.log("holder", holder.address, "peer", peer.address);

const create = await submit(
  {
    TransactionType: "MPTokenIssuanceCreate",
    Account: issuer.address,
    AssetScale: 0,
    Flags: { tfMPTCanLock: true, tfMPTRequireAuth: true, tfMPTCanClawback: true, tfMPTCanTransfer: true },
  },
  issuer,
);
const issuanceId = create.meta.mpt_issuance_id;
console.log("issuance", issuanceId, create.result);

for (const w of [holder, peer]) {
  await submit({ TransactionType: "MPTokenAuthorize", Account: w.address, MPTokenIssuanceID: issuanceId }, w);
  await submit(
    { TransactionType: "MPTokenAuthorize", Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: w.address },
    issuer,
  );
}
console.log("both opted in + approved");

console.log(
  "issuer->holder 100:",
  (await submit({ TransactionType: "Payment", Account: issuer.address, Destination: holder.address, Amount: { mpt_issuance_id: issuanceId, value: "100" } }, issuer)).result,
);
console.log(
  "issuer->peer 100:",
  (await submit({ TransactionType: "Payment", Account: issuer.address, Destination: peer.address, Amount: { mpt_issuance_id: issuanceId, value: "100" } }, issuer)).result,
);

console.log(
  "lock holder:",
  (await submit({ TransactionType: "MPTokenIssuanceSet", Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: holder.address, Flags: { tfMPTLock: true } }, issuer)).result,
);

console.log(
  "TEST issuer->holder (receive while locked) 1:",
  (await submit({ TransactionType: "Payment", Account: issuer.address, Destination: holder.address, Amount: { mpt_issuance_id: issuanceId, value: "1" } }, issuer)).result,
);

console.log(
  "TEST holder->issuer (send to issuer while locked) 1:",
  (await submit({ TransactionType: "Payment", Account: holder.address, Destination: issuer.address, Amount: { mpt_issuance_id: issuanceId, value: "1" } }, holder)).result,
);

console.log(
  "TEST holder->peer (send to peer while locked) 1:",
  (await submit({ TransactionType: "Payment", Account: holder.address, Destination: peer.address, Amount: { mpt_issuance_id: issuanceId, value: "1" } }, holder)).result,
);

console.log(
  "TEST peer->holder (receive from peer while locked) 1:",
  (await submit({ TransactionType: "Payment", Account: peer.address, Destination: holder.address, Amount: { mpt_issuance_id: issuanceId, value: "1" } }, peer)).result,
);

await client.disconnect();

