content.content:
1	/**
2	 * Issuer-side module for a regulated, stablecoin-style token on the XRP Ledger,
3	 * built on Multi-Purpose Tokens (MPTs, XLS-33).
4	 *
5	 * Wraps the MPT transaction family (MPTokenIssuanceCreate, MPTokenIssuanceSet,
6	 * MPTokenAuthorize, Clawback, Payment) with the compliance operations a
7	 * regulated issuer needs: allowlisting, clawback, per-holder freeze, global
8	 * freeze, and address bans. Every mutating call submits a transaction, waits
9	 * for validation, and throws if the ledger did not apply it.
10	 */
11	
12	import { RippledError } from "xrpl";
13	import type { Client, LedgerEntry, TxResponse, Wallet } from "xrpl";
14	import type {
15	  Clawback,
16	  MPTokenAuthorize,
17	  MPTokenIssuanceCreate,
18	  MPTokenIssuanceSet,
19	  Payment,
20	  SubmittableTransaction,
21	} from "xrpl";
22	
23	type MPToken = LedgerEntry.MPToken;
24	type MPTokenIssuance = LedgerEntry.MPTokenIssuance;
25	
26	/** Parameters accepted by {@link MptIssuer.createIssuance}. */
27	export interface IssuanceConfig {
28	  /** Decimal places the token can be subdivided into (0-255). Defaults to 2 (cents-like precision). */
29	  assetScale?: number;
30	  /** Hard cap on total outstanding supply, in the smallest unit. Defaults to no explicit cap (ledger max). */
31	  maximumAmount?: string;
32	  /** Secondary-sale transfer fee, in increments of 0.001% (0-50000). Requires holder-to-holder transfer to be enabled. */
33	  transferFee?: number;
34	  /** Metadata already hex-encoded (e.g. a JSON document per XLS-89), stored on the issuance, up to 1024 bytes. */
35	  metadataHex?: string;
36	  /** Allow holder-to-holder transfers, not just issuer<->holder. Defaults to true. */
37	  canTransfer?: boolean;
38	}
39	
40	/** Point-in-time compliance state of a single holder for this issuance. */
41	export interface HolderStatus {
42	  /** Whether the holder has an MPToken object at all (i.e. has opted in). */
43	  exists: boolean;
44	  /** Whether the issuer has authorized this holder to hold the token (allowlist). */
45	  authorized: boolean;
46	  /** Whether the issuer has individually frozen (locked) this holder's balance. */
47	  frozen: boolean;
48	  /** Current balance, in the smallest unit, as a decimal string. */
49	  balance: string;
50	}
51	
52	/** Point-in-time compliance state of the issuance as a whole. */
53	export interface IssuanceStatus {
54	  issuanceId: string;
55	  issuer: string;
56	  outstandingAmount: string;
57	  /** Whether all movement of the token is currently frozen (global freeze / lock). */
58	  globallyLocked: boolean;
59	  requireAuth: boolean;
60	  canClawback: boolean;
61	  canLock: boolean;
62	  canTransfer: boolean;
63	}
64	
65	const LSF_MPTOKEN_LOCKED = 0x00000001;
66	const LSF_MPTOKEN_AUTHORIZED = 0x00000002;
67	
68	const LSF_ISSUANCE_LOCKED = 0x00000001;
69	const LSF_ISSUANCE_CAN_LOCK = 0x00000002;
70	const LSF_ISSUANCE_REQUIRE_AUTH = 0x00000004;
71	const LSF_ISSUANCE_CAN_TRANSFER = 0x00000020;
72	const LSF_ISSUANCE_CAN_CLAWBACK = 0x00000040;
73	
74	/** Thrown when a submitted transaction is not applied successfully (i.e. does not reach `tesSUCCESS`). */
75	export class MptTransactionError extends Error {
76	  constructor(
77	    public readonly transactionType: string,
78	    public readonly transactionResult: string,
79	    public readonly txHash?: string,
80	  ) {
81	    super(
82	      `${transactionType} failed with ${transactionResult}${txHash ? ` (tx ${txHash})` : ""}`,
83	    );
84	    this.name = "MptTransactionError";
85	  }
86	}
87	
88	/**
89	 * Thrown when {@link MptIssuer.pay} is refused by an application-level compliance
90	 * check, before any transaction is submitted to the ledger.
91	 *
92	 * The MPT "lock" primitive (both per-holder and global) only blocks *peer-to-peer*
93	 * movement on-ledger: rippled still permits direct issuer<->holder payments even
94	 * while a holder or the whole issuance is locked (this mirrors legacy trust-line
95	 * freeze behavior, and was confirmed empirically against testnet). A locked holder
96	 * that "can't send or receive" and a global freeze that blocks "all movement" are
97	 * therefore compliance guarantees this module enforces in application code, on top
98	 * of the ledger-level protection for peer-to-peer transfers.
99	 */
100	export class MptComplianceError extends Error {
101	  constructor(message: string) {
102	    super(message);
103	    this.name = "MptComplianceError";
104	  }
105	}
106	
107	export class MptIssuer {
108	  /** The MPT issuance this instance operates on, once created or attached. */
109	  public issuanceId: string | undefined;
110	
111	  /**
112	   * @param client Connected (or connectable) xrpl.js Client. Lifecycle (connect/disconnect) is the caller's responsibility.
113	   * @param issuerWallet Wallet for the issuing account. Every issuer-signed transaction uses this wallet.
114	   * @param issuanceId Optional: attach to an issuance that already exists, instead of calling {@link createIssuance}.
115	   */
116	  constructor(
117	    private readonly client: Client,
118	    private readonly issuerWallet: Wallet,
119	    issuanceId?: string,
120	  ) {
121	    this.issuanceId = issuanceId;
122	  }
123	
124	  /** The issuer's classic address. */
125	  get issuerAddress(): string {
126	    return this.issuerWallet.address;
127	  }
128	
129	  // ---------------------------------------------------------------------
130	  // Issuance lifecycle
131	  // ---------------------------------------------------------------------
132	
133	  /**
134	   * Creates the MPT issuance with every compliance control this module supports
135	   * enabled: allowlist (RequireAuth), per-holder/global freeze (CanLock), and
136	   * clawback (CanClawback). Sets {@link issuanceId} on success.
137	   */
138	  async createIssuance(config: IssuanceConfig = {}): Promise<string> {
139	    const canTransfer = config.canTransfer ?? true;
140	
141	    const tx: MPTokenIssuanceCreate = {
142	      TransactionType: "MPTokenIssuanceCreate",
143	      Account: this.issuerWallet.address,
144	      AssetScale: config.assetScale ?? 2,
145	      Flags: {
146	        tfMPTCanLock: true,
147	        tfMPTRequireAuth: true,
148	        tfMPTCanClawback: true,
149	        tfMPTCanTransfer: canTransfer,
150	      },
151	      ...(config.maximumAmount !== undefined && { MaximumAmount: config.maximumAmount }),
152	      ...(config.transferFee !== undefined && { TransferFee: config.transferFee }),
153	      ...(config.metadataHex !== undefined && { MPTokenMetadata: config.metadataHex }),
154	    };
155	
156	    const response = await this.submit(tx);
157	    const meta = response.result.meta;
158	    if (!meta || typeof meta === "string" || !meta.mpt_issuance_id) {
159	      throw new Error(
160	        "MPTokenIssuanceCreate succeeded but the ledger did not return an mpt_issuance_id",
161	      );
162	    }
163	    this.issuanceId = meta.mpt_issuance_id;
164	    return this.issuanceId;
165	  }
166	
167	  // ---------------------------------------------------------------------
168	  // Allowlist (KYC gating)
169	  // ---------------------------------------------------------------------
170	
171	  /**
172	   * Holder-side opt-in: creates the holder's MPToken object. Must happen before
173	   * the issuer can authorize the holder, and before the holder can receive any
174	   * balance. Call with the holder's own wallet.
175	   */
176	  async optIn(holderWallet: Wallet): Promise<void> {
177	    const tx: MPTokenAuthorize = {
178	      TransactionType: "MPTokenAuthorize",
179	      Account: holderWallet.address,
180	      MPTokenIssuanceID: this.requireIssuanceId(),
181	    };
182	    await this.submit(tx, holderWallet);
183	  }
184	
185	  /**
186	   * Issuer-side allowlist grant: authorizes a holder (who must have already
187	   * opted in via {@link optIn}) to hold and receive this token. This is the
188	   * "approved after KYC" step.
189	   */
190	  async approveHolder(holderAddress: string): Promise<void> {
191	    const tx: MPTokenAuthorize = {
192	      TransactionType: "MPTokenAuthorize",
193	      Account: this.issuerWallet.address,
194	      MPTokenIssuanceID: this.requireIssuanceId(),
195	      Holder: holderAddress,
196	    };
197	    await this.submit(tx);
198	  }
199	
200	  /**
201	   * Issuer-side allowlist revocation: removes a holder's authorization so they
202	   * can no longer receive this token. Does not touch their balance or send-side
203	   * ability to return tokens to the issuer. Used internally by {@link ban};
204	   * exposed directly for revoking approval without a full ban.
205	   */
206	  async revokeHolderApproval(holderAddress: string): Promise<void> {
207	    const tx: MPTokenAuthorize = {
208	      TransactionType: "MPTokenAuthorize",
209	      Account: this.issuerWallet.address,
210	      MPTokenIssuanceID: this.requireIssuanceId(),
211	      Holder: holderAddress,
212	      Flags: { tfMPTUnauthorize: true },
213	    };
214	    await this.submit(tx);
215	  }
216	
217	  // ---------------------------------------------------------------------
218	  // Payments
219	  // ---------------------------------------------------------------------
220	
221	  /**
222	   * Sends `value` (in the smallest unit, as a decimal string) of this MPT from
223	   * `fromWallet` to `toAddress`. Refused with {@link MptComplianceError}, before
224	   * touching the ledger, if the issuance is globally frozen or if either party
225	   * is individually frozen — see that class's docs for why this check lives here
226	   * rather than relying on the ledger alone.
227	   */
228	  async pay(fromWallet: Wallet, toAddress: string, value: string): Promise<void> {
229	    await this.assertMovementAllowed(fromWallet.address, toAddress);
230	    const tx: Payment = {
231	      TransactionType: "Payment",
232	      Account: fromWallet.address,
233	      Destination: toAddress,
234	      Amount: { mpt_issuance_id: this.requireIssuanceId(), value },
235	    };
236	    await this.submit(tx, fromWallet);
237	  }
238	
239	  private async assertMovementAllowed(fromAddress: string, toAddress: string): Promise<void> {
240	    const issuance = await this.getIssuanceStatus();
241	    if (issuance.globallyLocked) {
242	      throw new MptComplianceError(
243	        `Cannot complete payment: MPT issuance ${issuance.issuanceId} is globally frozen`,
244	      );
245	    }
246	    for (const [address, role] of [
247	      [fromAddress, "sender"],
248	      [toAddress, "recipient"],
249	    ] as const) {
250	      if (address === this.issuerWallet.address) {
251	        continue;
252	      }
253	      const status = await this.getHolderStatus(address);
254	      if (status.frozen) {
255	        throw new MptComplianceError(`Cannot complete payment: ${role} ${address} is frozen`);
256	      }
257	    }
258	  }
259	
260	  // ---------------------------------------------------------------------
261	  // Freeze controls
262	  // ---------------------------------------------------------------------
263	
264	  /** Freezes a single holder: they can neither send nor receive this token until unfrozen. */
265	  async freezeHolder(holderAddress: string): Promise<void> {
266	    await this.setIssuance({ Holder: holderAddress, Flags: { tfMPTLock: true } });
267	  }
268	
269	  /** Lifts an individual holder freeze. */
270	  async unfreezeHolder(holderAddress: string): Promise<void> {
271	    await this.setIssuance({ Holder: holderAddress, Flags: { tfMPTUnlock: true } });
272	  }
273	
274	  /** Freezes all movement of the token, for every holder, e.g. during an incident. */
275	  async globalFreeze(): Promise<void> {
276	    await this.setIssuance({ Flags: { tfMPTLock: true } });
277	  }
278	
279	  /** Lifts a global freeze. */
280	  async globalUnfreeze(): Promise<void> {
281	    await this.setIssuance({ Flags: { tfMPTUnlock: true } });
282	  }
283	
284	  private async setIssuance(
285	    fields: Pick<MPTokenIssuanceSet, "Holder" | "Flags">,
286	  ): Promise<void> {
287	    const tx: MPTokenIssuanceSet = {
288	      TransactionType: "MPTokenIssuanceSet",
289	      Account: this.issuerWallet.address,
290	      MPTokenIssuanceID: this.requireIssuanceId(),
291	      ...fields,
292	    };
293	    await this.submit(tx);
294	  }
295	
296	  // ---------------------------------------------------------------------
297	  // Clawback
298	  // ---------------------------------------------------------------------
299	
300	  /** Claws back exactly `value` (smallest unit, decimal string) of this MPT from `holderAddress`. */
301	  async clawback(holderAddress: string, value: string): Promise<void> {
302	    const tx: Clawback = {
303	      TransactionType: "Clawback",
304	      Account: this.issuerWallet.address,
305	      Holder: holderAddress,
306	      Amount: { mpt_issuance_id: this.requireIssuanceId(), value },
307	    };
308	    await this.submit(tx);
309	  }
310	
311	  /** Claws back a holder's entire current balance. Returns the amount clawed back. A zero balance is a no-op. */
312	  async clawbackAll(holderAddress: string): Promise<string> {
313	    const { balance } = await this.getHolderStatus(holderAddress);
314	    if (balance === "0") {
315	      return "0";
316	    }
317	    await this.clawback(holderAddress, balance);
318	    return balance;
319	  }
320	
321	  // ---------------------------------------------------------------------
322	  // Bans
323	  // ---------------------------------------------------------------------
324	
325	  /**
326	   * Bans a holder: claws back their entire balance and revokes their allowlist
327	   * authorization, so they end up holding none of the token and cannot be paid
328	   * it again (the issuance requires authorization, and they no longer have it).
329	   */
330	  async ban(holderAddress: string): Promise<void> {
331	    await this.clawbackAll(holderAddress);
332	    await this.revokeHolderApproval(holderAddress);
333	  }
334	
335	  // ---------------------------------------------------------------------
336	  // Read-only status
337	  // ---------------------------------------------------------------------
338	
339	  /** Reads the current compliance state of a single holder for this issuance. */
340	  async getHolderStatus(holderAddress: string): Promise<HolderStatus> {
341	    const issuanceId = this.requireIssuanceId();
342	    let mptoken: MPToken;
343	    try {
344	      const response = await this.client.request({
345	        command: "ledger_entry",
346	        mptoken: { mpt_issuance_id: issuanceId, account: holderAddress },
347	        ledger_index: "validated",
348	      });
349	      // The installed xrpl typings omit the plain `MPToken` ledger entry from the
350	      // generic `LedgerEntry` union even though `mptoken` lookups return it;
351	      // narrow with a cast instead of trusting the declared response type.
352	      mptoken = response.result.node as unknown as MPToken;
353	    } catch (err) {
354	      if (err instanceof RippledError && this.isEntryNotFound(err)) {
355	        return { exists: false, authorized: false, frozen: false, balance: "0" };
356	      }
357	      throw err;
358	    }
359	
360	    return {
361	      exists: true,
362	      authorized: (mptoken.Flags & LSF_MPTOKEN_AUTHORIZED) !== 0,
363	      frozen: (mptoken.Flags & LSF_MPTOKEN_LOCKED) !== 0,
364	      // rippled omits MPTAmount from the ledger entry entirely when the balance is zero.
365	      balance: mptoken.MPTAmount ?? "0",
366	    };
367	  }
368	
369	  /** Reads the current compliance state of the issuance as a whole. */
370	  async getIssuanceStatus(): Promise<IssuanceStatus> {
371	    const issuanceId = this.requireIssuanceId();
372	    const response = await this.client.request({
373	      command: "ledger_entry",
374	      mpt_issuance: issuanceId,
375	      ledger_index: "validated",
376	    });
377	    const issuance = response.result.node as unknown as MPTokenIssuance;
378	
379	    return {
380	      issuanceId,
381	      issuer: issuance.Issuer,
382	      outstandingAmount: issuance.OutstandingAmount,
383	      globallyLocked: (issuance.Flags & LSF_ISSUANCE_LOCKED) !== 0,
384	      requireAuth: (issuance.Flags & LSF_ISSUANCE_REQUIRE_AUTH) !== 0,
385	      canClawback: (issuance.Flags & LSF_ISSUANCE_CAN_CLAWBACK) !== 0,
386	      canLock: (issuance.Flags & LSF_ISSUANCE_CAN_LOCK) !== 0,
387	      canTransfer: (issuance.Flags & LSF_ISSUANCE_CAN_TRANSFER) !== 0,
388	    };
389	  }
390	
391	  private isEntryNotFound(err: RippledError): boolean {
392	    const data = err.data as { error?: string } | undefined;
393	    return data?.error === "entryNotFound";
394	  }
395	
396	  // ---------------------------------------------------------------------
397	  // Internals
398	  // ---------------------------------------------------------------------
399	
400	  private requireIssuanceId(): string {
401	    if (!this.issuanceId) {
402	      throw new Error(
403	        "No MPT issuance is attached to this MptIssuer. Call createIssuance() first, or pass an issuanceId to the constructor.",
404	      );
405	    }
406	    return this.issuanceId;
407	  }
408	
409	  private async submit<T extends SubmittableTransaction>(
410	    tx: T,
411	    signer: Wallet = this.issuerWallet,
412	  ): Promise<TxResponse<T>> {
413	    const response = await this.client.submitAndWait(tx, { wallet: signer, autofill: true });
414	    const meta = response.result.meta;
415	    if (!meta || typeof meta === "string") {
416	      throw new Error(
417	        `${tx.TransactionType} produced no usable metadata (tx ${response.result.hash})`,
418	      );
419	    }
420	    if (meta.TransactionResult !== "tesSUCCESS") {
421	      throw new MptTransactionError(tx.TransactionType, meta.TransactionResult, response.result.hash);
422	    }
423	    return response;
424	  }
425	}
